/// <summary>
///
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormControlEventHandler(formControlStr(CustVendCreateNetting, METMarkMatchingInvoice), FormControlEventType::Clicked)]
public static void METAutoMarkMatchingInvoiceId_OnClicked(FormControl sender, FormControlEventArgs e)
{
    Map                         vendInvoiceMap      = new Map(Types::String, Types::Class);     
    FormCommandButtonControl    callerButton        = sender as FormCommandButtonControl;
    FormRun                     form                = callerButton.formRun();
    FormDataSource              vendDS_ds           = form.dataSource(formDataSourceStr(CustVendCreateNetting,VendNettingTransView)) as FormDataSource;
    VendNettingTransView        vendNettingTrans    = vendDS_ds.getFirst(true);

    while (vendNettingTrans)
    {
        if (vendNettingTrans.Invoice)
        {
            vendInvoiceMap.insert(vendNettingTrans.Invoice, vendNettingTrans);
        }
        vendNettingTrans = vendDS_ds.getNext();
    }

    // Loop through Customer transactions and mark if InvoiceId matches a Vendor transaction
    FormDataSource              custDS_ds = form.dataSource(formDataSourceStr(CustVendCreateNetting, CustNettingTransTotalView)) as FormDataSource;
    CustNettingTransTotalView   custNettingTrans    = custDS_ds.cursor();

    while (custNettingTrans)
    {
        if (custNettingTrans.Invoice && vendInvoiceMap.exists(custNettingTrans.Invoice))
        {
            form.markCustTrans(custNettingTrans);
            form.markVendTrans(vendInvoiceMap.lookup(custNettingTrans.Invoice));
        }
        custNettingTrans = custDS_ds.getNext();
    }

    form.calculateNettingTotal();
    form.setUpNettingAmountControl();
    form.refreshDataSource();
    form.managePostButton();
}

